test:
datasets = {'a': [10, 11, 12], 'b': [20, 21]}
batcher = WeightedDatasetBatcher(datasets, {'a': 2, 'b': 1}, 3, offset=3)
assert batcher.next_batch() == [('a', 12), ('a', 10), ('b', 21)]

data={'train':[{'id':1},{'id':2}]}
b=WeightedDatasetBatcher(data, {'train':3}, 3)
assert b.next_batch() == [('train',{'id':1}),('train',{'id':2}),('train',{'id':1})]
assert b.next_batch() == [('train',{'id':2}),('train',{'id':1}),('train',{'id':2})]
assert data == {'train':[{'id':1},{'id':2}]}
